using UnityEngine;using LWS.TruckSports;
namespace LWS.TruckFieldGoal {
// One scoring reference and one contact timeline per actual projectile.
public sealed class FieldGoalProjectile:MonoBehaviour {
 public FieldGoalMatch match;public Rigidbody body;public Collider shape;public bool truckProjectile;public string LastMissLabel{get;private set;}="";public bool Launched{get;private set;}public bool LaunchObserved{get;private set;}public bool ClearedGround{get;private set;}public int Launches{get;private set;}public int GroundContacts{get;private set;}public int PostContacts{get;private set;}public Vector3 LaunchVelocity{get;private set;}public Vector3 Reference=>body.worldCenterOfMass;
 Vector3 previous,previousBody,previousVelocity,previousAngular;Quaternion previousRotation;float groundFraction=float.PositiveInfinity;
 public void ResetShot(){Launched=ClearedGround=LaunchObserved=false;LaunchVelocity=Vector3.zero;LastMissLabel="";Launches=GroundContacts=PostContacts=0;groundFraction=float.PositiveInfinity;Snapshot();}
 public void Arm(){if(Launched)return;Launched=true;Launches++;LaunchObserved=false;Snapshot();}
 void Snapshot(){previous=Reference;previousBody=body.position;previousRotation=body.rotation;previousVelocity=body.linearVelocity;previousAngular=body.angularVelocity;}
 public void Observe(){if(!Launched||match.Projectile!=this||match.rules.AttemptLocked){Snapshot();return;}if(!LaunchObserved&&match.FlightAge>=Time.fixedDeltaTime*1.5f){LaunchVelocity=body.linearVelocity;LaunchObserved=true;Debug.Log("FIELD_GOAL_ACTUAL_POST_PHYSICS_LAUNCH velocity="+LaunchVelocity+" truckProjectile="+truckProjectile);}var current=Reference;float fraction,x,y;bool good=FieldGoalRules.ForwardGoal(previous.x,previous.y,previous.z,current.x,current.y,current.z,match.GoalZ,match.GoalHalfWidth,match.Crossbar,groundFraction,out fraction,out x,out y);if(good)match.Resolve(true,"GOOD!",new Vector3(x,y,match.GoalZ));else if(groundFraction<float.PositiveInfinity)match.Resolve(false,string.IsNullOrEmpty(LastMissLabel)?"SHORT · GROUND CONTACT":LastMissLabel,current);else if(previous.z<=match.GoalZ&&current.z>match.GoalZ&&current.z>previous.z){float t=(match.GoalZ-previous.z)/(current.z-previous.z);float cx=Mathf.Lerp(previous.x,current.x,t),cy=Mathf.Lerp(previous.y,current.y,t);LastMissLabel=Mathf.Abs(cx)>match.GoalHalfWidth?(cx<0?"WIDE LEFT":"WIDE RIGHT"):cy<match.Crossbar?"SHORT · BELOW THE BAR":"MISS";}ClearedGround|=shape.bounds.min.y>.12f;Snapshot();}
 void Contact(Collision collision,bool entering){if(!match.Live||match.Projectile!=this)return;if(!Launched){if(!truckProjectile&&entering&&collision.rigidbody==match.truck.body)match.FootContact(collision);return;}if(collision.collider==match.ground||match.stadiumBoard!=null&&match.stadiumBoard.IsRunoff(collision.collider)){if(!ClearedGround)return;GroundContacts++;for(int i=0;i<collision.contactCount;i++){var c=collision.GetContact(i);var local=Quaternion.Inverse(body.rotation)*(c.point-body.position);var oldPoint=previousBody+previousRotation*local;float separation=Mathf.Max(0,Vector3.Dot(oldPoint-c.point,c.normal));float incoming=Mathf.Max(0,-Vector3.Dot(previousVelocity+Vector3.Cross(previousAngular,oldPoint-previous),c.normal));float t=incoming>.001f?Mathf.Clamp01(separation/(incoming*Time.fixedDeltaTime)):1;groundFraction=Mathf.Min(groundFraction,t);}}else if(entering&&collision.collider.transform.IsChildOf(match.posts)){PostContacts++;match.PostHit(collision.relativeVelocity.magnitude);}}
 void OnCollisionEnter(Collision collision){Contact(collision,true);}void OnCollisionStay(Collision collision){Contact(collision,false);}
}
}
